"""Client that posts records to the ingestion API."""
import json
import os
import urllib.error
import urllib.request

# The endpoint is deployment-specific and deliberately not recorded in this
# repo, so it is provided via the INGESTION_ENDPOINT environment variable.
ENDPOINT = os.environ.get("INGESTION_ENDPOINT", "http://127.0.0.1:8080/ingest")


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status in (200, 201, 202):
                    accepted += 1
        except urllib.error.HTTPError as err:
            print(f"record {record.get('id')}: HTTP {err.code}", flush=True)
        except urllib.error.URLError as err:
            print(f"record {record.get('id')}: {err.reason}", flush=True)
    return accepted


def main():
    records = load_records()
    accepted = post_records(ENDPOINT, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()

"""Tiny stand-in for the ingestion API, for verifying sync.py locally."""
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


class Handler(BaseHTTPRequestHandler):
    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length)
        try:
            json.loads(body)
            self.send_response(202)
        except ValueError:
            self.send_response(400)
        self.end_headers()
        self.wfile.write(b'{"ok": true}')

    def log_message(self, *args):
        pass


if __name__ == "__main__":
    ThreadingHTTPServer(("127.0.0.1", 8080), Handler).serve_forever()
